function bodDateRange(d,cl,b){
  // Get min ini and max fin from PLAN for this bodega
  var ini="",fin="";
  var prefix=d+"|"+cl+"|"+b+"|";
  Object.keys(PLAN).forEach(function(k){
    if(k.indexOf(prefix)!==0)return;
    var e=PLAN[k];
    if(e.ini&&(!ini||e.ini<ini))ini=e.ini;
    if(e.fin&&(!fin||e.fin>fin))fin=e.fin;
  });
  if(!ini)return "";
  var fmtD=function(s){if(!s)return"";var p=s.split("-");return p[2]+"/"+p[1];};
  return fmtD(ini)+" — "+fmtD(fin);
}
