function procDateRange(procKey){
  var ini="",fin="";
  var nk=normProc(procKey);
  Object.keys(PLAN).forEach(function(k){
    var parts=k.split("|");
    if(parts.length<4)return;
    // Match by paso key (last part)
    var paso=normProc(parts[3]||"");
    // Also check proceso from liveData
    var e=PLAN[k];
    if(e.ini&&(!ini||e.ini<ini))ini=e.ini;
    if(e.fin&&(!fin||e.fin>fin))fin=e.fin;
  });
  return "";
}
function procDateRangeByProc(procName){
  var ini="",fin="";
  var filas=LD2.filas||[];
  var nk=normProc(procName);
  filas.forEach(function(r){
    if(normProc(r["Proceso"]||"").indexOf(nk)<0)return;
    var bodNum=(r["Bodega"]||"").replace("Bodega ","");
    var paso=r["Paso"]||r["Proceso"]||"";
    var key=r["Distrito"]+"|"+r["Cluster"]+"|Bodega "+bodNum+"|"+paso;
    var e=PLAN[key];
    if(!e)return;
    if(e.ini&&(!ini||e.ini<ini))ini=e.ini;
    if(e.fin&&(!fin||e.fin>fin))fin=e.fin;
  });
  if(!ini)return "";
  var fmtD=function(s){if(!s)return"";var p=s.split("-");return p[2]+"/"+p[1];};
  return "<span class=\"proc-dates\">"+fmtD(ini)+" — "+fmtD(fin)+"</span>";
}
