function RC2(){
  var s=new Date("2026-06-16T00:00:00"),e=new Date("2026-09-27T00:00:00"),td=Math.ceil((e-s)/86400000);
  var lab=[],proj=[],real=[],trend=[];
  var rows=LD2.filas||[];
  // Calculate real current %
  var rtot=0,racc=0;
  rows.forEach(function(r){var av=parseFloat(r["% Avance"]||0);rtot++;racc+=av/100;});
  var rreal=rtot?Math.round(racc/rtot*100):0;
  // Find current day index
  var TODAY2=new Date();TODAY2.setHours(0,0,0,0);
  var dayNow=Math.max(0,Math.ceil((TODAY2-s)/86400000));
  // Calculate trend ratio: real/expected at today
  var projToday=0;
  if(dayNow>0&&dayNow<=td){projToday=Math.round(Math.min(100,dayNow/td*100));}
  var ratio=projToday>0?(rreal/projToday):1;
  for(var day=0;day<=td;day+=7){
    var d2=new Date(s.getTime()+day*86400000);
    lab.push(d2.toLocaleDateString("es-GT",{day:"2-digit",month:"short"}));
    // Projected S-curve (planned)
    var sa=new Date("2026-06-16T00:00:00"),ea=new Date("2026-08-30T00:00:00");
    var sb=new Date("2026-07-11T00:00:00"),eb=new Date("2026-09-27T00:00:00");
    var pA=0,pB=0;
    if(d2>=sa){var tA=Math.ceil((ea-sa)/86400000);pA=Math.min(100,Math.round((d2-sa)/86400000/tA*100));}
    if(d2>=sb){var tB=Math.ceil((eb-sb)/86400000);pB=Math.min(100,Math.round((d2-sb)/86400000/tB*100));}
    proj.push(Math.round((pA*36+pB*20)/56));
    // Real (only up to today)
    if(day<=dayNow){real.push(rreal>0?Math.round(rreal*(day/Math.max(dayNow,1))):null);}
    else{real.push(null);}
    // Trend projection: extrapolate current ratio to full project
    var trendVal=Math.min(100,Math.round(Math.round((pA*36+pB*20)/56)*ratio));
    trend.push(trendVal);
  }
  var ctx=ge("cs").getContext("2d");
  if(sch)sch.destroy();
  sch=new Chart(ctx,{type:"line",data:{labels:lab,datasets:[
    {label:"Plan",data:proj,borderColor:"#185FA5",backgroundColor:"#185FA520",borderWidth:2,pointRadius:2,fill:true,tension:0.4},
    {label:"Real",data:real,borderColor:"#E07B2A",backgroundColor:"transparent",borderWidth:2.5,pointRadius:3,fill:false,tension:0.3,spanGaps:false},
    {label:"Tendencia proyectada",data:trend,borderColor:"#A32D2D",backgroundColor:"transparent",borderWidth:2,borderDash:[6,4],pointRadius:0,fill:false,tension:0.4}
  ]},options:{responsive:true,plugins:{legend:{position:"top",labels:{font:{size:11},usePointStyle:true}},tooltip:{callbacks:{label:function(c){return c.dataset.label+": "+c.parsed.y+"%";}}}},scales:{y:{max:100,ticks:{callback:function(v){return v+"%";},font:{size:10}},grid:{color:"#E5E5E3"}},x:{ticks:{font:{size:9},maxTicksLimit:12},grid:{display:false}}}}});
}
function RBC2(){
  // Weekly bar chart: planned % vs real % per week
  var s=new Date("2026-06-16T00:00:00"),e=new Date("2026-09-27T00:00:00"),td=Math.ceil((e-s)/86400000);
  var TODAY2=new Date();TODAY2.setHours(0,0,0,0);
  var rows=LD2.filas||[];
  var rtot=0,racc=0;
  rows.forEach(function(r){var av=parseFloat(r["% Avance"]||0);rtot++;racc+=av/100;});
  var rreal=rtot?Math.round(racc/rtot*100):0;
  var dayNow=Math.max(0,Math.ceil((TODAY2-s)/86400000));
  var lab=[],planData=[],realData=[];
  var sa=new Date("2026-06-16T00:00:00"),ea=new Date("2026-08-30T00:00:00");
  var sb=new Date("2026-07-11T00:00:00"),eb=new Date("2026-09-27T00:00:00");
  for(var day=0;day<=Math.min(td,dayNow+49);day+=7){
    var d2=new Date(s.getTime()+day*86400000);
    lab.push(d2.toLocaleDateString("es-GT",{day:"2-digit",month:"short"}));
    var pA=0,pB=0;
    if(d2>=sa){var tA=Math.ceil((ea-sa)/86400000);pA=Math.min(100,Math.round((d2-sa)/86400000/tA*100));}
    if(d2>=sb){var tB=Math.ceil((eb-sb)/86400000);pB=Math.min(100,Math.round((d2-sb)/86400000/tB*100));}
    var planPct=Math.round((pA*36+pB*20)/56);
    planData.push(planPct);
    // Real: proportional to dayNow
    var realPct=day<=dayNow?Math.round(rreal*(day/Math.max(dayNow,1))):null;
    realData.push(realPct);
  }
  var ctx=ge("bc5").getContext("2d");
  if(bch)bch.destroy();
  bch=new Chart(ctx,{type:"bar",data:{labels:lab,datasets:[
    {label:"% Plan",data:planData,backgroundColor:"#185FA580",borderColor:"#185FA5",borderWidth:1,borderRadius:3},
    {label:"% Real",data:realData,backgroundColor:"#E07B2A",borderColor:"#C4621A",borderWidth:1,borderRadius:3}
  ]},options:{responsive:true,plugins:{legend:{position:"top",labels:{font:{size:11},usePointStyle:true}},
    datalabels:{display:true,anchor:"end",align:"top",formatter:function(v){return v!==null?v+"%":"";},font:{size:9},color:function(c){return c.datasetIndex===0?"#185FA5":"#E07B2A";}}
  },scales:{y:{max:100,ticks:{callback:function(v){return v+"%";},font:{size:10}},grid:{color:"#E5E5E3"}},x:{ticks:{font:{size:9}},grid:{display:false}}}}});
}
