var LD2={},SFF="all",CV="dist",CD=null,CC=null,CB=null,CU="A",bch=null,sch=null,cch=null;

function dt(s){return new Date(s+"T00:00:00");}
function SS(ini,fin,av){
  var f=dt(fin),i=dt(ini);
  if(av>=100)return "done";
  if(TODAY<i)return "pend";
  if(TODAY>f)return "late";
  var el=(TODAY-i)/(f-i),exp=Math.round(Math.min(100,el*100));
  if(av>=exp)return "ok";
  if(av>=exp*0.65)return "risk";
  return "late";
}
function GR2(d,cl,b,pk){
  if(!LD2.filas)return [];
  return LD2.filas.filter(function(r){
    return r["Distrito"]===d&&r["Cluster"]===cl&&r["Bodega"]===b&&normProc(r["Proceso"]||"").indexOf(pk)>=0;
  });
}
function PA(d,cl,b,pi){
  var rows=GR2(d,cl,b,PK[pi]);
  if(!rows.length)return 0;
  var s=0;
  rows.forEach(function(r){s+=parseFloat(r["% Avance"]||0);});
  return Math.round(s/rows.length);
}
function OGBod(d,cl,b,procKey){
  if(!LD2.filas)return 0;
  var normKey=normProc(procKey);
  var rows=LD2.filas.filter(function(r){
    return r["Distrito"]===d&&r["Cluster"]===cl&&r["Bodega"]===b&&
      normProc(r["Proceso"]||"").indexOf(normKey)>=0;
  });
  if(!rows.length)return 0;
  return Math.round(rows.reduce(function(s,r){return s+parseFloat(r["% Avance"]||0);},0)/rows.length);
}
function WP(d,cl,b){
  // Dynamic normalization: only include processes that exist for this bodega
  // Each process has a defined weight; sum only weights of processes present in KV data
  var procDefs=[
    {k:"Mezanines y Techados",  fn:function(){return PA(d,cl,b,0);}, w:15, std:true},
    {k:"Estructura Principal",  fn:function(){return PA(d,cl,b,1);}, w:15, std:true},
    {k:"Acabados",              fn:function(){return PA(d,cl,b,2);}, w:10, std:true},
    {k:"Cimentacion",           fn:function(){return OGBod(d,cl,b,"Cimentacion");},           w:10, std:false},
    {k:"Muro Cifa",             fn:function(){return OGBod(d,cl,b,"Muro Cifa");},             w:8,  std:false},
    {k:"Levantado de Block",    fn:function(){return OGBod(d,cl,b,"Levantado de Block");},    w:5,  std:false},
    {k:"Contrapisos",           fn:function(){return OGBod(d,cl,b,"Contrapisos");},           w:11, std:false},
    {k:"Inst. Electricas",      fn:function(){return OGBod(d,cl,b,"Inst. Electricas");},      w:5,  std:false},
    {k:"Muro Nailing",          fn:function(){return OGBod(d,cl,b,"Muro Nailing");},          w:2,  std:false},
    {k:"Fundicion de Piso",     fn:function(){return OGBod(d,cl,b,"Fundicion de Piso");},     w:5,  std:false},
    {k:"Muro de Contencion",    fn:function(){return OGBod(d,cl,b,"Muro de Contencion");},    w:1,  std:false},
    {k:"Muro de Culata",        fn:function(){return OGBod(d,cl,b,"Muro de Culata");},        w:1,  std:false},
  ];
  var filas=LD2.filas||[];
  var totalW=0,weightedSum=0;
  for(var i=0;i<procDefs.length;i++){
    var pd=procDefs[i];
    // Check if this process has any data for this bodega
    var hasData=false;
    if(pd.std){
      // Standard process: check if rows exist in KV
      var normK=normProc(pd.k);
      hasData=filas.some(function(r){
        return r["Distrito"]===d&&r["Cluster"]===cl&&r["Bodega"]===b&&
          normProc(r["Proceso"]||"").indexOf(normK)>=0;
      });
    } else {
      // OG process: check PLAN keys for this bodega
      var bodNum=b.replace("Bodega ","");
      var prefix=d+"|"+cl+"|Bodega "+bodNum+"|"+pd.k;
      hasData=Object.keys(PLAN).some(function(k){return k.indexOf(prefix)===0;});
    }
    if(!hasData)continue;
    var av=pd.fn();
    weightedSum+=pd.w*av;
    totalW+=pd.w;
  }
  if(!totalW)return 0;
  return Math.round(weightedSum/totalW);
}
function CP(d,cl){var bs=DB[d][cl];return Math.round(bs.reduce(function(s,b){return s+WP(d,cl,b);},0)/bs.length);}
function DP(d){var cls=Object.keys(DB[d]);return Math.round(cls.reduce(function(s,cl){return s+CP(d,cl);},0)/cls.length);}
function TP(){
  // Weighted total: Mez15+Est15+Acab10+Cim10+Cifa8+Block5+Contra11+Elec5+Urba12+Nailing2+Fund5+ContMur1+Culata1=100%
  var mez=0,est=0,acab=0,tot=0,cnt=0;
  ["Distrito A","Distrito B"].forEach(function(d){
    Object.keys(DB[d]).forEach(function(cl){
      DB[d][cl].forEach(function(b){
        mez+=PA(d,cl,b,0);
        est+=PA(d,cl,b,1);
        acab+=PA(d,cl,b,2);
        cnt++;
      });
    });
  });
  var avgMez=cnt?Math.round(mez/cnt):0;
  var avgEst=cnt?Math.round(est/cnt):0;
  var avgAcab=cnt?Math.round(acab/cnt):0;
  var avgCim=OGAvg("Cimentacion");
  var avgCifa=OGAvg("Muro Cifa");
  var avgBlock=OGAvg("Levantado de Block en Fachada");
  var avgContra=OGAvg("Contrapisos");
  var avgElec=OGAvg("Inst. Electricas");
  var avgNailing=OGAvg("Muro Nailing");
  var avgFund=OGAvg("Fundicion de Piso");
  var avgContMur=OGAvg("Muro de Contencion");
  var avgCulata=OGAvg("Muro de Culata");
  var urbaRows=(LD2.filas||[]).filter(function(r){return r["Proceso"]==="Urbanizacion"||r["Proceso"]==="Urbanización";});
  var avgUrba=urbaRows.length?Math.round(urbaRows.reduce(function(s,r){return s+parseFloat(r["% Avance"]||0);},0)/urbaRows.length):0;
  return Math.round(
    avgMez*0.15+avgEst*0.15+avgAcab*0.10+
    avgCim*0.10+avgCifa*0.08+avgBlock*0.05+
    avgContra*0.11+avgElec*0.05+avgUrba*0.12+
    avgNailing*0.02+avgFund*0.05+avgContMur*0.01+avgCulata*0.01
  );
}
function CD2(){
  var n=0;
  ["Distrito A","Distrito B"].forEach(function(d){Object.keys(DB[d]).forEach(function(cl){DB[d][cl].forEach(function(b){if(WP(d,cl,b)===100)n++;});});});
  return n;
}
function CL(){
  // Count bodegas that are behind schedule
  var n=0;
  ["Distrito A","Distrito B"].forEach(function(d){
    Object.keys(DB[d]).forEach(function(cl){
      DB[d][cl].forEach(function(b){
        if(WS(d,cl,b)==="late")n++;
      });
    });
  });
  return n;
}
function procStatus(ini,fin,av){
  if(!ini||!fin)return "pend";
  var i=new Date(ini+"T00:00:00"),f=new Date(fin+"T00:00:00");
  if(TODAY<i)return "pend";
  if(av>=100)return "ok";
  if(TODAY>f)return "late";
  var el=(TODAY-i)/(f-i);
  var exp=Math.round(Math.min(100,el*100));
  var gap=exp-av;
  if(gap>=30)return "late";
  if(gap>=15)return "risk";
  return "ok";
}
function WS(d,cl,b){
  var late=0,risk=0,ok=0,pend=0;
  var allProcs=[
    "Cimentacion","Muro Cifa","Levantado de Block en Fachada",
    "Contrapisos","Inst. Electricas","Mezanines y Techados",
    "Estructura Principal","Acabados","Muro Nailing",
    "Fundicion de Piso","Muro de Contencion","Muro de Culata"
  ];
  var filas=LD2.filas||[];
  var bodNum=b.replace("Bodega ","");
  for(var pi=0;pi<allProcs.length;pi++){
    var proc=allProcs[pi];
    var normP=normProc(proc);
    // Get actual % from live data
    var rows=filas.filter(function(r){
      return r["Distrito"]===d&&r["Cluster"]===cl&&r["Bodega"]===b&&
        normProc(r["Proceso"]||"").indexOf(normP)>=0;
    });
    var av=rows.length?Math.round(rows.reduce(function(s,r){return s+parseFloat(r["% Avance"]||0);},0)/rows.length):0;
    // Find all PLAN entries for this proceso (may have multiple pasos)
    var prefix=d+"|"+cl+"|Bodega "+bodNum+"|"+proc+"|";
    var planKeys=Object.keys(PLAN).filter(function(k){return k.indexOf(prefix)===0;});
    if(!planKeys.length){pend++;continue;}
    // Use min(ini) and max(fin) across all pasos
    var inis=planKeys.map(function(k){return PLAN[k].ini;}).filter(Boolean).sort();
    var fins=planKeys.map(function(k){return PLAN[k].fin;}).filter(Boolean).sort();
    if(!inis.length||!fins.length){pend++;continue;}
    var st=procStatus(inis[0],fins[fins.length-1],av);
    if(st==="late")late++;
    else if(st==="risk")risk++;
    else if(st==="ok")ok++;
    else pend++;
  }
  if(late>0)return "late";
  if(risk>0)return "risk";
  if(ok>0)return "ok";
  return "pend";
}
function ge(id){return document.getElementById(id);}
function ce(tag,cls,html){var e=document.createElement(tag);if(cls)e.className=cls;if(html)e.innerHTML=html;return e;}

function ST(tab){
  document.querySelectorAll(".scr").forEach(function(s){s.classList.remove("on");});
  document.querySelectorAll(".nb").forEach(function(b){b.classList.remove("on");});
  ge("s-"+tab).classList.add("on");
  ge("bn-"+tab).classList.add("on");
  if(tab==="r")RR();
  else if(tab==="b")RB();
  else if(tab==="u")RU();
  else if(tab==="s")RS();
  else if(tab==="rp")RRP();
}

